			interchange3.EI_InterchangeNum = "2299569";

			var message1 = Factory.NewWithValidTestData<CMRCARSTMessage>();
			message1.EM_EI = interchange1.PK;
			message1.EM_MessageNum = "00000000371260000003";
			message1.EM_MessageText = "UNH+000003+CUSRES:D:99B:UN'BGM+34:::CARST+1087 7453 18GE:1+8'DTM+9:20141217094234481043:ZZZ'DTM+132:20141217:102'FTX+AHN+++CONSOLIDATED STATUS:CLEAR'FTX+AHN+++CARGO REPORT SAC:YES'TDT+20+765++6+QF::3'LOC+12+AUBNE::6'LOC+4+9912J::95'NAD+MR+AAA374M::95'NAD+UD+41065894724::95'RFF+ABO:A00266315/CMT1::1'RFF+MWB:08177661776'RFF+HWB:8999999'DOC+1'PAC+0000001'UNT+17+000003'";
