			message5.EM_MessageNum = "00000000371260000004";
			message5.EM_MessageText = "UNH+000004+CUSRES:D:99B:UN'BGM+34:::CARST+3DHE 1BF3 18GE:1+8'DTM+9:20141217094234485782:ZZZ'DTM+132:20141217:102'FTX+AHN+++CONSOLIDATED STATUS:CLEAR'FTX+AHN+++CARGO REPORT SAC:YES'TDT+20+765++6+QF::3'LOC+12+AUBNE::6'LOC+4+9912J::95'NAD+MR+AAA374M::95'NAD+UD+41065894724::95'RFF+ABO:A00266316/CMT1::1'RFF+MWB:08177661776'RFF+HWB:9999999'DOC+1'PAC+0000001'UNT+17+000004'";
