			message6.EM_EI = interchange3.PK;
			message6.EM_MessageNum = "00000000371258000003";
			message6.EM_MessageText = "UNH+000003+CUSRES:D:99B:UN'BGM+34:::CARST+3J9J A8C6 G8GE:1+8'DTM+9:20141217094157760565:ZZZ'DTM+132:20141217:102'FTX+AHN+++CONSOLIDATED STATUS:HELD'FTX+AHN+++DEPARTURE FROM LAST OVERSEAS PORT:YES'FTX+AHN+++QUOTED MASTER / OCEAN BILL EXISTS:YES'FTX+AHN+++IAR ACS CLEARED:YES'FTX+AHN+++COMPLETE UNDERBOND SERIES APPROVED:N/A'FTX+AHN+++LCL UNDERBOND SATISFIED:N/A'FTX+AHN+++DECONSOLIDATION UNDERBOND SATISFIED:YES'FTX+AHN+++CARGO NOT A CONSOLIDATION:YES'FTX+AHN+++RELEASE PREMISE IN DESTINATION:YES'FTX+AHN+++CARGO REPORT ACS EVALUATED:YES'FTX+AHN+++IAR AQIS CLEARED:YES'FTX+AHN+++CARGO REPORT AQIS EVALUATED:YES'FTX+AHN+++IMPORT DECLARATIONS MATCHED:N/A'FTX+AHN+++IMPORT DECLARATION ACS EVALUATED:N/A'FTX+AHN+++IMPORT DECLARATION AQIS EVALUATED:N/A'FTX+AHN+++ACS EVALUATION COMPLETE:YES'FTX+AHN+++AQIS CARGO REPORT EVALUATION COMPLETE:YES'FTX+AHN+++ACS IMPORT DECLARATION EVALUATION COMPLETE:N/A'FTX+AHN+++AQIS IMPORT DECLARATION EVALUATION COMPLETE:N/A'FTX+AHN+++IMPORT DECLARATION PAID:N/A'FTX+AHN+++CARGO REPORT SAC:NO'TDT+20+765++6+QF::3'LOC+12+AUBNE::6'LOC+4+9912J::95'NAD+MR+AAA374M::95'NAD+UD+41065894724::95'RFF+ABO:A00266308/CMT1::1'RFF+MWB:08177661776'RFF+HWB:1999999'UNT+34+000003'";

