			messages.Add(message5);
			messages.Add(message6);

			sortedMessages = AUEDIMessageComparer.GetSortedMessages(messages, ListSortDirection.Descending);
			AssertEquals("Messages should be sorted descendingly", "00000000371258000003", sortedMessages[0].EM_MessageNum);
			AssertEquals("Messages should be sorted descendingly", "00000000371260000004", sortedMessages[1].EM_MessageNum);
